  const fmtDate=t=>new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric'}).format(t);
  const fmtTime=t=>new Intl.DateTimeFormat('en-US',{hour:'numeric',minute:'2-digit'}).format(t);
  const duration=s=>s>=3600?`${Math.floor(s/3600)}h ${Math.floor(s%3600/60)}m`:s>=60?`${Math.floor(s/60)}m`:`${Math.max(0,Math.round(s))}s`;
  const label=p=>p?.label||p?.handle||'Unknown profile';
